//Variables Externas
var LA = Ua.findNode("AGENT.OBJECTS.Simulation.Sistema_Llenado_Tanque.Llenado_Activo");
var CE = Ua.findNode("AGENT.OBJECTS.Simulation.Sistema_Llenado_Tanque.Caudal_Entrada");

//If the water flow is different than 0
if(CE.result.value>0){
	LA.result.assign({value:true});
}
else{
	LA.result.assign({value:false});
}
